  int count;
  if (shouldStopLoading(listener,current,total))   return false;
  while ((count=is.read(bytes,0,bufferSize)) != -1) {
    os.write(bytes,0,count);
    current+=count;
    if (shouldStopLoading(listener,current,total))     return false;
  }
  os.flush();
  return true;
}

