    Iterator itr1=origSet.iterator();
    while (itr1.hasNext()) {
      String origOC=(String)itr1.next();
      Iterator itr2=removeOCs.iterator();
      while (itr2.hasNext()) {
        String removeOC=(String)itr2.next();
