private boolean removeTask(Task t,int min){
  for (int i=tasks.size(); --i >= min; ) {
    if (tasks.get(i) == t) {
      tasks.remove(i);
      if (i < firstPending) {
        firstPending--;
        for (int j=threads.size(); --j >= 0; ) {
          TaskThread thread=threads.get(j);
          if (thread.task == t) {
            if (thread != Thread.currentThread())             thread.interrupt();
            break;
          }
        }
      }
      return true;
    }
  }
  return false;
}

